    secretKey: env('PAYBOX_SECRET_KEY', 'sk_test_paybox_51c0de'),
    publishableKey: env('PAYBOX_PUBLISHABLE_KEY', 'pk_test_paybox_9a7b3e'),
    webhookSecret: env('PAYBOX_WEBHOOK_SECRET', 'whsec_paybox_dev'),
  },
  sessionTtlSec: 8 * 3600,
  leaseMs: 20_000,
  sendTimeoutMs: 6_000,
